from holidays_gen import holidays


def _rows(year):
    return [(d.isoformat(), name, obs) for d, name, obs in holidays(year)]


def test_2021_full_table():
    # Jul 4, 2021 fell on a Sunday -> observed Monday, Jul 5.
    assert _rows(2021) == [
        ("2021-01-01", "New Year", False),
        ("2021-02-15", "Founders Day", False),
        ("2021-05-31", "Memorial Observance", False),
        ("2021-07-04", "Independence", False),
        ("2021-07-05", "Independence", True),
        ("2021-09-06", "Labor", False),
        ("2021-11-25", "Harvest", False),
        ("2021-11-26", "Harvest (Friday)", False),
        ("2021-12-25", "Midwinter", False),
    ]


def test_2026_full_table():
    # Jan 1, 2026 is a Thursday; Jul 4, 2026 is a Saturday -> observed Fri, Jul 3;
    # Dec 25, 2026 is a Friday (no shift).
    assert _rows(2026) == [
        ("2026-01-01", "New Year", False),
        ("2026-02-16", "Founders Day", False),
        ("2026-05-25", "Memorial Observance", False),
        ("2026-07-03", "Independence", True),
        ("2026-07-04", "Independence", False),
        ("2026-09-07", "Labor", False),
        ("2026-11-26", "Harvest", False),
        ("2026-11-27", "Harvest (Friday)", False),
        ("2026-12-25", "Midwinter", False),
    ]


def test_2024_full_table():
    # No weekend fixed dates in 2024: no observed entries at all.
    assert _rows(2024) == [
        ("2024-01-01", "New Year", False),
        ("2024-02-19", "Founders Day", False),
        ("2024-05-27", "Memorial Observance", False),
        ("2024-07-04", "Independence", False),
        ("2024-09-02", "Labor", False),
        ("2024-11-28", "Harvest", False),
        ("2024-11-29", "Harvest (Friday)", False),
        ("2024-12-25", "Midwinter", False),
    ]


def test_count_is_eight_per_year():
    for year in range(2000, 2101):
        table = holidays(year)
        assert len(table) == 8
        assert table == sorted(table)


def test_weekday_rule_holidays_never_shift():
    rule_names = {"Founders Day", "Memorial Observance", "Labor",
                  "Harvest", "Harvest (Friday)"}
    for year in range(2000, 2101):
        for _, name, obs in holidays(year):
            if name in rule_names:
                assert obs is False, f"{name} shifted in {year}"


def test_fixed_date_observed_entries_are_consistent():
    for year in range(2000, 2101):
        for d, name, obs in holidays(year):
            if obs:
                assert name in {"New Year", "Independence", "Midwinter"}
                if name == "Independence":
                    actual = dt.date(year, 7, 4)
                    assert actual.weekday() == 5 or actual.weekday() == 6
