                    assert d == dt.date(year, 1, 1)
                elif name == "Independence":
                    assert d == dt.date(year, 7, 4)
                elif name == "Midwinter":
                    assert d == dt.date(year, 12, 25)


def test_harvest_friday_sweep_2000_2100():
    for year in range(2000, 2101):
        by_name = {name: d for d, name, _ in holidays(year)}
        harvest = by_name["Harvest"]
        friday = by_name["Harvest (Friday)"]
        assert harvest.weekday() == 3                       # Thursday
        assert friday - harvest == dt.timedelta(days=1)     # next day
